function filterList(inputId,listId){
  var q=document.getElementById(inputId).value.toLowerCase();
  document.querySelectorAll('#'+listId+' li').forEach(function(li){
    li.style.display=li.textContent.toLowerCase().indexOf(q)>=0?'':'none';
  });
}
function toggleSidebar(){
  var sb=document.querySelector('.sidebar');
  sb.classList.toggle('open');
  var btn=document.querySelector('.sb-toggle');
  btn.textContent=sb.classList.contains('open')?'\u2715 Cerrar navegación':'\u2630 Explorar plantas y medicamentos';
}
